<?php
$teams = fetch_all('SELECT * FROM teams ORDER BY sort_order,id');
$edit = isset($_GET['edit']) ? fetch_one('SELECT * FROM players WHERE id=?', [(int) $_GET['edit']]) : null;
$selected = selected_positions($edit['positions']??[]);
$filterTeam = (int)($_GET['team']??0);
$params=[];$where='1=1';if($filterTeam){$where.=' AND p.team_id=?';$params[]=$filterTeam;}
$players = fetch_all("SELECT p.*,t.name team_name,t.logo team_logo,t.accent team_accent FROM players p JOIN teams t ON t.id=p.team_id WHERE {$where} ORDER BY p.active DESC,t.sort_order,p.sort_order,p.jersey_no",$params);
$usedNumbers=[];foreach($teams as $team){$usedNumbers[$team['id']]=array_map('intval',array_column(fetch_all('SELECT jersey_no FROM players WHERE team_id=? AND active=1 AND jersey_no IS NOT NULL',[$team['id']]),'jersey_no'));}
?>
<div class="split-layout wide-preview">
