<input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="player_save"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><input type="hidden" name="old_photo" value="<?= e($edit['photo']??'') ?>">
<div class="panel-head"><div><small>KADRO YÖNETİMİ</small><h2><?= $edit?'Oyuncuyu düzenle':'Yeni oyuncu ekle' ?></h2></div><?php if($edit):?><a href="?section=players">Yeni oyuncu +</a><?php endif; ?></div>
<div class="form-grid"><label>Takım<select name="team_id" data-player-team required><?php foreach($teams as $team):?><option value="<?= $team['id'] ?>" data-name="<?= e($team['name']) ?>" data-logo="<?= e($team['logo']?media_url($team['logo']):'') ?>" data-accent="<?= e($team['accent']) ?>" <?= ($edit['team_id']??0)==$team['id']?'selected':'' ?>><?= e($team['name']) ?></option><?php endforeach; ?></select></label><label>Ad soyad<input name="name" value="<?= e($edit['name']??'') ?>" data-live="player-name" required></label><label>URL kısa adı<input name="slug" value="<?= e($edit['slug']??'') ?>" placeholder="oyuncu-adi"></label><label>Forma numarası (1-99)<input type="number" min="1" max="99" name="jersey_no" value="<?= e($edit['jersey_no']??'') ?>" data-live="player-number" required><small class="field-status" data-number-status>Seçilen takımda benzersiz olmalıdır.</small></label>
<fieldset class="full position-picker"><legend>Oynadığı mevkiler</legend><?php foreach(positions() as $position):?><label><input type="checkbox" name="positions[]" value="<?= e($position) ?>" <?= in_array($position,$selected,true)?'checked':'' ?> data-position><span><?= e($position) ?></span></label><?php endforeach; ?></fieldset>
