<section class="panel"><div class="panel-head"><div><small>KADRO LİSTESİ</small><h2>Oyuncular</h2></div><form method="get" class="inline-filter"><input type="hidden" name="section" value="players"><select name="team" onchange="this.form.submit()"><option value="0">Tüm takımlar</option><?php foreach($teams as $team):?><option value="<?= $team['id'] ?>" <?= $filterTeam===$team['id']?'selected':'' ?>><?= e($team['name']) ?></option><?php endforeach; ?></select></form></div><div class="admin-player-grid"><?php foreach($players as $player):$pos=selected_positions($player['positions']);?><article class="admin-player-row <?= $player['active']?'':'archived' ?>"><img src="<?= e($player['photo']?media_url($player['photo']):silhouette()) ?>" alt=""><div><small><?= e($player['team_name']) ?> · <?= e(implode(', ',$pos)) ?></small><h3>#<?= e($player['jersey_no']??'-') ?> <?= e($player['name']) ?></h3><p><?= e($player['previous_clubs']?:'Önceki kulüp bilgisi yok') ?></p></div><span class="badge <?= $player['active']?'green':'gray' ?>"><?= $player['active']?'Aktif':'Arşiv' ?></span><div class="row-actions"><a href="?section=players&edit=<?= $player['id'] ?>">Düzenle</a><a href="<?= e(url('index.php?page=player&slug='.urlencode($player['slug']))) ?>" target="_blank">Profil ↗</a><?php if($player['active']):?><form method="post" onsubmit="return confirm('Oyuncu arşivlensin ve forma numarası serbest bırakılsın mı?')"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="player_archive"><input type="hidden" name="id" value="<?= $player['id'] ?>"><button class="danger-link">Arşivle</button></form><?php endif; ?></div></article><?php endforeach; ?><?php if(!$players):?><div class="empty-admin">Henüz oyuncu eklenmedi.</div><?php endif; ?></div></section>
